#define MS 1000000LL
#define S 1000000000LL

static void test_rise_then_onset(void)
{
	struct fusion f;
	int64_t dt = 0;

	fusion_init(&f, 3 * S);
	CHECK(fusion_rise(&f, 100 * S, &dt) == 0);		/* nothing heard yet */
	CHECK(fusion_onset(&f, 100 * S + 2900 * MS, &dt) == 1);
