	fusion_init(&f, 3 * S);
	CHECK(fusion_rise(&f, 100 * S, NULL) == 0);
	CHECK(fusion_onset(&f, 100 * S + 3100 * MS, NULL) == 0);	/* too late */
}

static void test_onset_then_rise(void)
{
	struct fusion f;
	int64_t dt = 0;

