	fusion_init(&f, 3 * S);
	CHECK(fusion_onset(&f, 50 * S, &dt) == 0);
	CHECK(fusion_rise(&f, 51 * S, &dt) == 1);
	CHECK(dt == -1 * S);

	fusion_init(&f, 3 * S);
	CHECK(fusion_onset(&f, 50 * S, NULL) == 0);
	CHECK(fusion_rise(&f, 54 * S, NULL) == 0);	/* sound was 4 s before */
}

