		pss_log("event %" PRIu64 ": motion+sound, but %s: not an entry", ev->id, arm_state_name(h->arm.state));
		return;
	}
	ev->kind = PSS_EV_ENTRY;
	memset(&o, 0, sizeof o);
	o.event_id = ev->id;
	o.start_mono_ns = ev->start_mono_ns;
	o.start_wall_ns = ev->start_wall_ns;
	o.kind = PSS_EV_ENTRY;
	o.flags = ev->flags;
