1	/*
2	 * hub: the single writer (DESIGN.md Section 2). Accepts sensor daemons on
3	 * $PSS_RUN_DIR/hub.sock, turns PIR edges into events, asks camd for an image
4	 * burst per event, and commits everything through the store (mechanism D).
5	 *
6	 * Fusion (DESIGN.md Section 4, src/analysis/fusion.c): a PIR rise opens a
7	 * MOTION_ONLY event and a sound onset (below) opens a SOUND_ONLY event, but
8	 * neither takes images. Only when a rise and an onset fall within +-T_co of
9	 * each other (either order) does the event become an ENTRY: it is made
10	 * durable at once and camd is asked for a burst. While the ENTRY stays open
11	 * and the device is watching, a burst repeats every --reburst-ms after the
12	 * first, until --reburst-cap-ms after it (default: at 0-4 min, 5 bursts).
13	 * Repeat bursts are appended to the same clips/<id>.dir (clip_append).
14	 *
15	 * M3 sound trigger (stand-in for DESIGN.md Section 4's detectors, M4): an
16	 * EWMA background model of spectral flux and log RMS, learned only while no
17	 * event is open. A frame is an onset when its flux z-score and its loudness
18	 * above the room background both pass thresholds, so steady noise (fans,
19	 * AC) never triggers: its flux stays near its own mean and its level is the
20	 * background. Thresholds are placeholders until tuned on Pi recordings.
21	 *
22	 * Arm state (DESIGN.md Section 4, src/analysis/arm.c): pird's button presses
23	 * and confirmed entries drive it, and every change is made durable as a
24	 * PSS_REC_ARM record, the last of which is restored at start. New events
25	 * open, and the camera fires, only while ARMED or in GRACE; an event already
26	 * open when the device is disarmed finishes normally. The LED (not wired
27	 * yet, Owen's side) is only logged.
28	 *
29	 * Exit codes: 0 on SIGTERM/SIGINT, 1 on error (including any store write
30	 * failure, so the supervisor restarts us and recovery runs), 2 on usage.
31	 */
32	#include "analysis/arm.h"
33	#include "analysis/fusion.h"
34	#include "common/ipc.h"
35	#include "common/log.h"
36	#include "common/suphb.h"
37	#include "common/time.h"
38	#include "common/util.h"
39	#include "store/clip.h"
40	#include "store/evlog.h"
41	
42	#include <errno.h>
43	#include <getopt.h>
44	#include <inttypes.h>
45	#include <math.h>
46	#include <signal.h>
47	#include <stdio.h>
48	#include <string.h>
49	#include <sys/epoll.h>
50	#include <sys/signalfd.h>
51	#include <sys/socket.h>
52	#include <sys/stat.h>
53	#include <unistd.h>
54	
55	#define EXIT_USAGE 2
56	#define MAX_CONNS 8
57	#define HB_FIRST_NS (5 * PSS_NS_PER_S)
58	#define HB_EVERY_NS (60 * PSS_NS_PER_S)
59	#define HB_STALE_NS (15 * PSS_NS_PER_S)
60	#define SUPHB_EVERY_NS (5 * PSS_NS_PER_S)	/* to the supervisor, like every daemon */
61	#define BURST_SLACK_NS (20 * PSS_NS_PER_S)
62	#define BURST_EST_BYTES (9ull * 1024 * 1024)	/* upper end of DESIGN.md Section 5's 6-9 MB */
63	#define MIC_ALPHA_MIN (1.0 / 3000)	/* 60 s time constant at 50 frames/s */
64	#define MIC_FLUX_VAR_FLOOR (0.05 * 0.05)
65	#define MIC_LRMS_VAR_FLOOR (0.01 * 0.01)
66	#define MIC_RMS_FLOOR 1e-6		/* keeps log10 finite on digital silence */
67	
68	enum { TAG_LISTEN = MAX_CONNS, TAG_SIG, TAG_TICK };
69	
70	struct conn {
71		int fd;
72		uint32_t role;		/* PSS_ROLE_NONE until HELLO */
73		int64_t last_hb_ns;
74	};
75	
76	enum burst_state { BURST_NONE, BURST_PENDING, BURST_DONE };
77	
78	struct event {
79		int open;
80		uint64_t id;
81		uint32_t kind;		/* PSS_EV_ENTRY once confirmed; else set at close */
82		int64_t start_mono_ns;
83		int64_t start_wall_ns;
84		int64_t last_activity_ns;
85		int pir_high;
86		uint32_t pir_edges;
87		uint32_t flags;
88		uint32_t n_images;
89		enum burst_state burst;
90		int64_t burst_deadline_ns;
91		uint32_t bursts;	/* asked for, including failed ones */
92		int64_t first_burst_ns;
93	};
94	
95	/* EWMA mean/variance of flux and log10(rms), learned outside events. */
96	struct mic_bg {
97		uint64_t n;
98		double flux_mu, flux_var;
99		double lrms_mu, lrms_var;
100		double z_max, db_max;	/* largest scores since the last heartbeat, for tuning */
101	};
102	
103	struct hub {
104		struct pss_store store;
105		int store_open;
106		int listen_fd, epoll_fd, sig_fd, tick_fd;
107		struct conn conns[MAX_CONNS];
108		struct event ev;
109		struct mic_bg mic;
110		struct fusion fu;
111		struct arm arm;
112		int fatal;		/* a store write failed inside a handler: exit so recovery runs */
113		int64_t start_ns, next_hb_ns, next_suphb_ns;
114		uint64_t pir_edges, mic_frames, cam_bursts, cam_failures, events_closed, mic_onsets;
115		/* config */
