	voice_step(a, vz >= a->k_voice && zb[0] < vz, r);

	if (learn) {
		if (zf > a->imp_zmax)
			a->imp_zmax = zf;
		if (vz > a->voice_zmax)
			a->voice_zmax = vz;
		if (!transient)
			learn_frame(a, flux, band);
	}
	return 0;
}

