	AUDIO_IMPULSE = 1,	/* an impulse was confirmed (impulse_ns, impulse_z) */
	AUDIO_VOICE_START = 2,	/* voice just became detected */
	AUDIO_VOICE = 4,	/* voice is detected (every frame while it is) */
};

/*
